// evaluateGuard evaluates a guard condition via script engine.
// W3C SCXML 4.3.2: If a condition expression cannot be evaluated, the processor
// MUST treat it as false and MUST raise error.execution.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) evaluateGuard(guard string, eng *sce.Engine[AChildTakesAHandedValueInPlaceOfItsDataState, AChildTakesAHandedValueInPlaceOfItsDataEvent]) bool {
	value, _ := p.evaluateGuardRaising(guard, eng, "a <transition> cond failed to evaluate")
	return value
}

// evaluateIfCond evaluates an <if> or <elseif> cond as evaluateGuard does, and
// also records a failure in condFailed. W3C SCXML 5.9.1 + 4.9: the <if> still
// selects on false, and is then the element whose processing raised, so its
// block ends after it.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) evaluateIfCond(guard string, eng *sce.Engine[AChildTakesAHandedValueInPlaceOfItsDataState, AChildTakesAHandedValueInPlaceOfItsDataEvent], condFailed *bool) bool {
	value, ok := p.evaluateGuardRaising(guard, eng, "an <if> cond failed to evaluate")
	if !ok {
		*condFailed = true
	}
	return value
}

// evaluateGuardRaising evaluates a cond, raising error.execution when it cannot
// be evaluated (W3C SCXML 5.9.1); ok is false then, where a bare false could
// not say so.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) evaluateGuardRaising(guard string, eng *sce.Engine[AChildTakesAHandedValueInPlaceOfItsDataState, AChildTakesAHandedValueInPlaceOfItsDataEvent], reason string) (value bool, ok bool) {
	p.assertScriptSession()
	engine := p.ScriptEngine
	result, err := engine.EvaluateExpression(p.SessionID, guard)
	if err != nil {
		eng.Raise(sce.NewPlatformError(AChildTakesAHandedValueInPlaceOfItsDataEventErrorExecution, reason))
		return false, false
	}
	return sce.ScriptToBool(result), true
}

// executeScript executes a script block via script engine.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) executeScript(script string) error {
	p.assertScriptSession()
	engine := p.ScriptEngine
	return engine.ExecuteScript(p.SessionID, script)
}

// setCurrentEvent binds _event system variable (W3C SCXML 5.10) and answers
// which rung of §scxml-B-2-8-1 the payload got, because the binding is the
// only place that knows.
//
// This used to be `_ = engine.SetCurrentEvent(...)`: the ladder decided
// between a DOM, a value and a space-normalized string, and the decision was
// dropped one line later. A payload that announced structure and would not
// parse therefore reached the document as raw characters, every
// _event.data.<field> read empty, and nothing anywhere could say so — see
// sce.PayloadReading.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) setCurrentEvent(name string) sce.PayloadReading {
	p.assertScriptSession()
	engine := p.ScriptEngine
	data := p.pendingEventData
	eventType := p.pendingEventType
	sendID := p.pendingEventSendid
	// W3C SCXML 5.10.1 + C.1: `_event.origin` and `_event.origintype` are the
	// one pair the processor that delivered the event wrote when it built it
	// (docs/adr/0090) — the sender's published `_ioprocessors` location for a
	// session's send — read here as they are, and both empty for none.
	// Nothing converts at this boundary, so every backend answers the same.
	origin := p.pendingEventOrigin.Address()
	originType := p.pendingEventOrigin.Processor()
	invokeID := p.pendingEventInvokeid
	reading, err := engine.SetCurrentEvent(p.SessionID, sce.SetCurrentEventArgs{
		Name:       name,
		Data:       data,
		Type:       eventType,
		SendID:     sendID,
		Origin:     origin,
		OriginType: originType,
		InvokeID:   invokeID,
	})
	if err != nil {
		// An engine that could not bind _event at all has a larger problem
		// than an unreadable payload, and reporting PayloadUndecodable for it
		// would point a host at the wrong thing.
		return sce.PayloadAbsent
	}
	return reading
}

// assignVariable assigns a value to a datamodel variable via script engine.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) assignVariable(location, expr string) error {
	p.assertScriptSession()
	engine := p.ScriptEngine
	script := location + " = " + expr
	return engine.ExecuteScript(p.SessionID, script)
}

// getVariable reads a datamodel variable from the script engine.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) getVariable(name string) interface{} {
	p.assertScriptSession()
	engine := p.ScriptEngine
	result, err := engine.GetVariable(p.SessionID, name)
	if err != nil {
		return nil
	}
	return result
}

// SetParamValueInScriptEngine hands this machine, before its start, the value
// an invoking session evaluated for one `<param>` or `namelist` name
// (§scxml-6.4). The invoking session hands every name it evaluated; this
// machine's start (InitializeDataModel) decides which it keeps, from the ids
// of its own top-level `<data>`, and declares each kept one as that `<data>`'s
// initial value in place of its own (docs/adr/0098). Nothing is written to the
// script session here: the session is the child's own, established by its
// start (docs/adr/0096).
//
// The value crosses as a value: this took the parent's value rendered as Lua
// source and re-evaluated it here until 2026-08-21, which survived every value
// a test had tried and lost the ones Lua cannot spell — `ToScriptLiteral`
// renders a non-finite number as `+Inf`, which is not a Lua expression, so an
// `<invoke>` `<param expr="1/0"/>` arrived as nothing at all.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) SetParamValueInScriptEngine(name string, value interface{}) {
	if p.handedValues == nil {
		p.handedValues = make(map[string]interface{})
	}
	p.handedValues[name] = value
}

// declareHandedValue declares the top-level `<data>` name with the value an
// invoking session handed for it (§scxml-6.4), in place of the `<data>`'s own
// `expr`, `src` or content, which is not evaluated. A value the session cannot
// hold is the error of that `<data>`'s initialization (§scxml-5.3):
// error.execution, and the `<data>` left unset, as one whose own expression
// failed is left (docs/adr/0098).
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) declareHandedValue(eng *sce.Engine[AChildTakesAHandedValueInPlaceOfItsDataState, AChildTakesAHandedValueInPlaceOfItsDataEvent], engine sce.IScriptEngine, sessionID, name string, value interface{}) {
	if err := engine.SetVariable(sessionID, name, value); err != nil {
		eng.Raise(sce.NewPlatformError(AChildTakesAHandedValueInPlaceOfItsDataEventErrorExecution, "<data id='"+name+"'> could not hold the value its invoking session handed it"))
		_ = engine.SetVariable(sessionID, name, nil)
	}
}


