// TickChildren ticks child state machines (W3C SCXML 6.4).
// Port of Rust do_tick_children().
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) TickChildren(engine *sce.Engine[AChildTakesAHandedValueInPlaceOfItsDataState, AChildTakesAHandedValueInPlaceOfItsDataEvent]) {
	if !p.pendingDoneInvokeByParam && p.childByParam != nil {
		child := p.childByParam
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "by_param", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "by_param", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeByParam {
			p.pendingDoneInvokeByParam = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("by_param", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeByNamelist && p.childByNamelist != nil {
		child := p.childByNamelist
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "by_namelist", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "by_namelist", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeByNamelist {
			p.pendingDoneInvokeByNamelist = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("by_namelist", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeLateBound && p.childLateBound != nil {
		child := p.childLateBound
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "late_bound", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "late_bound", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeLateBound {
			p.pendingDoneInvokeLateBound = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("late_bound", child.DonedataAtFinal(), engine)
		}
	}
	if !p.pendingDoneInvokeFirstMacrostep && p.childFirstMacrostep != nil {
		child := p.childFirstMacrostep
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "first_macrostep", engine)
		// Child sessions in Mesh (SCE_MESH.md): what arrived for the child on
		// the router it was given, before its macrostep.
		child.ApplyMeshCalls()
		child.Tick()
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "first_macrostep", engine)
		if child.IsInFinalState() && !p.pendingDoneInvokeFirstMacrostep {
			p.pendingDoneInvokeFirstMacrostep = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("first_macrostep", child.DonedataAtFinal(), engine)
		}
	}
}

// SettleChildren settles what every running child sent this machine while it was
// driven by a delivery (sce.ChildSettler; docs/adr/0045): the events it sent
// `#_parent` are raised here, and a child that reached its final state raises
// `done.invoke` once. One body for every drive of a child, so a save at any
// boundary of this session finds the child's buffer empty.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) SettleChildren(engine *sce.Engine[AChildTakesAHandedValueInPlaceOfItsDataState, AChildTakesAHandedValueInPlaceOfItsDataEvent]) {
	if child := p.childByParam; child != nil && !p.pendingDoneInvokeByParam {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "by_param", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeByParam = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("by_param", child.DonedataAtFinal(), engine)
		}
	}
	if child := p.childByNamelist; child != nil && !p.pendingDoneInvokeByNamelist {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "by_namelist", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeByNamelist = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("by_namelist", child.DonedataAtFinal(), engine)
		}
	}
	if child := p.childLateBound; child != nil && !p.pendingDoneInvokeLateBound {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "late_bound", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeLateBound = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("late_bound", child.DonedataAtFinal(), engine)
		}
	}
	if child := p.childFirstMacrostep; child != nil && !p.pendingDoneInvokeFirstMacrostep {
		sce.DrainAndRaiseChildEvents(child, p.activeInvokes, "first_macrostep", engine)
		if child.IsInFinalState() {
			p.pendingDoneInvokeFirstMacrostep = true
			// The session ended: its Mesh router is told so.
			child.DetachMesh()
			// W3C SCXML 5.5 + 6.3.1: Lift the child's stashed donedata onto
			// done.invoke.<id>._event.data.
			sce.RaiseDoneInvoke("first_macrostep", child.DonedataAtFinal(), engine)
		}
	}
}

// AdoptHostInvokersInChildren hands the tree's host invokers on to every child
// this machine holds now (sce.HostInvokeChildren; docs/adr/0045): a child a
// restore resumed holds children of its own, resumed with it before its parent
// could hand it anything.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) AdoptHostInvokersInChildren(invokers *sce.TreeInvokers) {
	if tree, ok := p.childByParam.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
	if tree, ok := p.childByNamelist.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
	if tree, ok := p.childLateBound.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
	if tree, ok := p.childFirstMacrostep.(sce.HostInvokeTree); ok {
		tree.AdoptHostInvokers(invokers)
	}
}

// RouteHostInvokeEndToChild delivers the ending of a host-run invocation to the
// child at or below which the session sessionID is (sce.HostInvokeChildren), and
// answers false when no running child holds it.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) RouteHostInvokeEndToChild(sessionID string, ending sce.HostInvokeEnding) (bool, error) {
	if tree, ok := p.childByParam.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	if tree, ok := p.childByNamelist.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	if tree, ok := p.childLateBound.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	if tree, ok := p.childFirstMacrostep.(sce.HostInvokeTree); ok {
		if routed, err := tree.RouteHostInvokeEnd(sessionID, ending); routed {
			return true, err
		}
	}
	return false, nil
}

// NextChildDeadline reports the nearest deadline among the running children
// (W3C SCXML 6.4), so a host that walks time by TimeUntilNextScheduled does not
// step over a timer a child armed. The ticking above is what makes it this
// machine's. A child that has ended (pendingDoneInvoke) is skipped: the policy
// keeps it until its state exits, and what it armed is no longer owed.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) NextChildDeadline() (time.Duration, bool) {
	var soonest time.Duration
	found := false
	if !p.pendingDoneInvokeByParam && p.childByParam != nil {
		if due, ok := p.childByParam.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeByNamelist && p.childByNamelist != nil {
		if due, ok := p.childByNamelist.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeLateBound && p.childLateBound != nil {
		if due, ok := p.childLateBound.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	if !p.pendingDoneInvokeFirstMacrostep && p.childFirstMacrostep != nil {
		if due, ok := p.childFirstMacrostep.TimeUntilNextScheduled(); ok && (!found || due < soonest) {
			soonest, found = due, true
		}
	}
	return soonest, found
}


// DeliverToInvocation delivers a delayed `<send target="#_<invokeid>">` whose
// wait is over, by name — a child need not declare every event its parent
// sends (W3C SCXML 6.2 + 6.4). It answers whether the invocation was there to
// take it: one whose session has reached its final state has ended, and the
// engine reports the send it could not deliver (W3C SCXML C.1). sender is the
// session that sent it, this one, whose location the child reads as
// `_event.origin` (docs/adr/0090).
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) DeliverToInvocation(invokeID, eventName, eventData, sendID, sender string) bool {
	if invokeID == "by_param" {
		if child := p.childByParam; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData, sender)
			return true
		}
		return false
	}
	if invokeID == "by_namelist" {
		if child := p.childByNamelist; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData, sender)
			return true
		}
		return false
	}
	if invokeID == "late_bound" {
		if child := p.childLateBound; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData, sender)
			return true
		}
		return false
	}
	if invokeID == "first_macrostep" {
		if child := p.childFirstMacrostep; child != nil && !child.IsInFinalState() {
			sce.DeliverToChild(child, eventName, eventData, sender)
			return true
		}
		return false
	}
	return false
}

// IsInvocationRunning reports whether `#_<invokeid>` names an invocation running
// now (W3C SCXML 6.4 + C.1) — one whose session has reached its final state has
// ended, and a send naming it is reported when it is made.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) IsInvocationRunning(invokeID string) bool {
	if invokeID == "by_param" {
		child := p.childByParam
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "by_namelist" {
		child := p.childByNamelist
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "late_bound" {
		child := p.childLateBound
		return child != nil && !child.IsInFinalState()
	}
	if invokeID == "first_macrostep" {
		child := p.childFirstMacrostep
		return child != nil && !child.IsInFinalState()
	}
	return false
}

// IsChildSessionRunning reports whether a session id names a child of this
// machine that is running now (W3C SCXML C.1) — the test DeliverToChildSession
// makes.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) IsChildSessionRunning(childSessionID string) bool {
	if childSessionID == "" {
		return false
	}
	if cs, ok := p.activeInvokes["by_param"]; ok && cs.SessionID == childSessionID {
		child := p.childByParam
		return child != nil && !child.IsInFinalState()
	}
	if cs, ok := p.activeInvokes["by_namelist"]; ok && cs.SessionID == childSessionID {
		child := p.childByNamelist
		return child != nil && !child.IsInFinalState()
	}
	if cs, ok := p.activeInvokes["late_bound"]; ok && cs.SessionID == childSessionID {
		child := p.childLateBound
		return child != nil && !child.IsInFinalState()
	}
	if cs, ok := p.activeInvokes["first_macrostep"]; ok && cs.SessionID == childSessionID {
		child := p.childFirstMacrostep
		return child != nil && !child.IsInFinalState()
	}
	return false
}

// DeliverToChildSession delivers an event addressed to a child's published
// location (W3C SCXML C.1).
//
// The parent mints `parentSession.invokeId` for each child and that id is what
// the child's `_ioprocessors` entry names, so a <send> whose target decodes to
// one of them is addressed to that child rather than to this machine. A false
// return means the address names no live child of ours and the event takes the
// normal external path — the routing half of C.1 is what makes the published
// location a usable target rather than a string that merely compares equal.
func (p *AChildTakesAHandedValueInPlaceOfItsDataPolicy) DeliverToChildSession(childSessionID, eventName, eventData, sender string) bool {
	if !p.IsChildSessionRunning(childSessionID) {
		return false
	}
	if cs, ok := p.activeInvokes["by_param"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childByParam, eventName, eventData, sender)
		return true
	}
	if cs, ok := p.activeInvokes["by_namelist"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childByNamelist, eventName, eventData, sender)
		return true
	}
	if cs, ok := p.activeInvokes["late_bound"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childLateBound, eventName, eventData, sender)
		return true
	}
	if cs, ok := p.activeInvokes["first_macrostep"]; ok && cs.SessionID == childSessionID {
		sce.DeliverToChild(p.childFirstMacrostep, eventName, eventData, sender)
		return true
	}
	return false
}


